    trig=[("immutable", ["definition_id", "param_key", "proposed_value", "requested_by", "reason"]),
          trans("status", ["PENDING_APPROVAL>APPROVED", "PENDING_APPROVAL>REJECTED", "PENDING_APPROVAL>CANCELLED", "PENDING_APPROVAL>EXPIRED"]),
          ("raw", ["CREATE TRIGGER tg_param_change_request_value BEFORE INSERT ON @param_change_request FOR EACH ROW EXECUTE FUNCTION @tg_param_value_check('proposed_value');"])],
