     ("fk_replay_item_dlq", f"FOREIGN KEY (tenant_id, dlq_id, dlq_received_at) REFERENCES {S}.dlq_message (tenant_id, id, received_at) ON DELETE CASCADE"),
     chk("replay_item", "idem", "idempotency_key = dlq_id::text || ':' || revision_no::text"),
     chk("replay_item", "status", f"status IN {X('PENDING', 'SENT', 'SUCCEEDED', 'FAILED', 'SKIPPED_DUPLICATE', 'CANCELLED')}"),
