G_NOTIFY = []
G_NOTIFY.append(T("notification_template", "EN-18-19",
    "Mẫu thông báo (thư, SMS, trong ứng dụng) của các PH: mã mẫu, PH sở hữu, nhóm DD-13, thông báo bắt buộc (không tắt bằng tùy chọn), khẩn (bỏ qua giờ yên lặng). Dòng COMMON là mẫu mặc định nền tảng, tenant ghi đè cùng mã. Nội dung ở notification_template_version.",
    ["template_code varchar(64) NOT NULL", "owner_module varchar(8) NOT NULL", "title varchar(255) NOT NULL", "description varchar(1000)", "category varchar(12) NOT NULL",
     "channels varchar(8)[] NOT NULL", "mandatory boolean NOT NULL DEFAULT false", "urgent boolean NOT NULL DEFAULT false", "active_version_no integer", "retired_at timestamptz"],
    [("uq_notification_template_code", "UNIQUE (tenant_id, template_code)"),
     chk("notification_template", "code", "template_code ~ '^[a-z0-9]+(\\.[a-z0-9-]+)+$'"), chk("notification_template", "module", f"owner_module ~ '{MODULE_RE}'"),
     chk("notification_template", "category", f"category IN {X('TASK', 'JOB_RESULT', 'ALERT', 'INFO')}"),
     chk("notification_template", "channels", "cardinality(channels) >= 1 AND channels <@ ARRAY['EMAIL', 'SMS', 'IN_APP']::varchar(8)[]")],
    rls="common", trig=[("immutable", ["template_code", "owner_module"])],
    sample={"template_code": "'ph01.review-decided'", "owner_module": "'PH01'", "title": "'Kết quả thẩm định'", "category": "'INFO'", "channels": "'{EMAIL,IN_APP}'"}))

G_NOTIFY.append(T("notification_template_version", "EN-18-20",
    "Phiên bản nội dung mẫu Mustache không logic: tiêu đề thư, thân, SMS, tiêu đề và liên kết trong ứng dụng, danh sách biến cho phép. Duyệt (IN_REVIEW sang ACTIVE) chỉ khi kiểm tra cấm trường mức Hạn chế, Nhạy cảm đạt (FR-00-062); người duyệt khác người soạn. Từ IN_REVIEW nội dung bất biến; mỗi mẫu, ngôn ngữ một bản ACTIVE.",
    ["template_id uuid NOT NULL", "version_no integer NOT NULL", "locale varchar(8) NOT NULL DEFAULT 'vi'", "email_subject varchar(255)", "body_text text",
     "body_html text", "sms_text varchar(480)", "in_app_title varchar(255)", "in_app_link varchar(500)", "allowed_fields varchar(64)[] NOT NULL DEFAULT '{}'",
     "field_check_passed boolean NOT NULL DEFAULT false", "field_check_report jsonb", "status varchar(12) NOT NULL DEFAULT 'DRAFT'", "submitted_at timestamptz",
     "reviewed_by varchar(64)", "reviewed_at timestamptz", "activated_at timestamptz", "retired_at timestamptz"],
    [("uq_notification_template_version_no", "UNIQUE (tenant_id, template_id, version_no, locale)"),
     fk("notification_template_version", "template_id", "notification_template"),
     chk("notification_template_version", "no", "version_no >= 1"), chk("notification_template_version", "status", f"status IN {X(*ST_TEMPLATE)}"),
     chk("notification_template_version", "content", "body_text IS NOT NULL OR sms_text IS NOT NULL OR in_app_title IS NOT NULL"),
     chk("notification_template_version", "link", "in_app_link IS NULL OR in_app_link ~ '^/[a-z0-9/_{}?=&.-]*$'"),
     four_eyes("notification_template_version", "reviewed_by"),
     chk("notification_template_version", "active", "status NOT IN ('ACTIVE', 'RETIRED') OR (field_check_passed AND reviewed_by IS NOT NULL AND activated_at IS NOT NULL)"),
     chk("notification_template_version", "no_logic", "coalesce(body_text, '') || coalesce(body_html, '') || coalesce(sms_text, '') !~ '\\{\\{[#^/>]'")],
    idx=["CREATE UNIQUE INDEX uq_notification_template_version_active ON @notification_template_version (tenant_id, template_id, locale) WHERE status = 'ACTIVE';"],
    rls="common", trig=[("immutable", ["template_id", "version_no", "locale"]),
                        ("frozen", ["IN_REVIEW,ACTIVE,RETIRED", "email_subject", "body_text", "body_html", "sms_text", "in_app_title", "in_app_link", "allowed_fields"]),
                        trans("status", ["DRAFT>IN_REVIEW", "IN_REVIEW>DRAFT", "IN_REVIEW>ACTIVE", "ACTIVE>RETIRED"])],
    ccomment={"body_text": "Mustache không logic: chỉ biến {{ten}} trong allowed_fields; CHECK chặn khối {{#}}, {{^}}, partial {{>}}.",
              "field_check_report": "Kết quả kiểm tra cấm trường mức Hạn chế, Nhạy cảm theo PH-09 (FR-00-062)."},
    sample={"version_no": "1", "body_text": "'Hồ sơ {{maHoSo}} đã có kết quả thẩm định.'", "allowed_fields": "'{maHoSo}'"}))

G_NOTIFY.append(T("notification_rule", "EN-18-21",
    "Quy tắc thông báo theo sự kiện của các PH (hợp đồng §1.3): loại sự kiện, điều kiện lọc, mẫu, cách phân giải người nhận, kênh, loại việc tạo kèm. Dòng COMMON là quy tắc nền tảng, tenant thêm hoặc tắt.",
    ["rule_code varchar(64) NOT NULL", "source_module varchar(8) NOT NULL", "event_type varchar(255) NOT NULL", "condition jsonb NOT NULL DEFAULT '{}'",
     "template_code varchar(64) NOT NULL", "recipient_kind varchar(16) NOT NULL", "recipient_expr varchar(255) NOT NULL", "channels varchar(8)[] NOT NULL",
     "create_task_type varchar(64)", "priority varchar(8) NOT NULL DEFAULT 'NORMAL'", "enabled boolean NOT NULL DEFAULT true"],
    [("uq_notification_rule_code", "UNIQUE (tenant_id, rule_code)"),
     chk("notification_rule", "module", f"source_module ~ '{MODULE_RE}'"),
     chk("notification_rule", "event", "event_type ~ '^[a-z0-9-]+(\\.[a-z0-9-]+)+\\.v[0-9]+$'"),
     chk("notification_rule", "recipient", f"recipient_kind IN {X('USER', 'GROUP', 'ROLE', 'SYSTEM_CONTACT', 'EVENT_FIELD', 'ON_CALL')}"),
     chk("notification_rule", "channels", "cardinality(channels) >= 1 AND channels <@ ARRAY['EMAIL', 'SMS', 'IN_APP']::varchar(8)[]"),
     chk("notification_rule", "priority", "priority IN ('NORMAL', 'URGENT')")],
    idx=["CREATE INDEX ix_notification_rule_event ON @notification_rule (event_type) WHERE enabled;"],
    rls="common", trig=[("immutable", ["rule_code"])],
    sample={"rule_code": "'ph01-review-decided'", "source_module": "'PH01'", "event_type": "'onboarding.review.decided.v1'", "template_code": "'ph01.review-decided'",
            "recipient_kind": "'EVENT_FIELD'", "recipient_expr": "'submittedBy'", "channels": "'{IN_APP}'"}))

G_NOTIFY.append(T("notification_message", "EN-18-22",
    "Thông báo logic (outbox của NotificationApi, DD-13): khóa lũy đẳng của bên gọi, mẫu và phiên bản, người nhận recipient_ref (người, nhóm, vai trò, đầu mối HTTT; PH-18 tự phân giải địa chỉ), biến mẫu (CHECK chặn trường định danh), chế độ ASYNC hoặc SYNC (thư mang liên kết, Q01-52), trạng thái tổng hợp từ các lần gửi.",
    ["caller_module varchar(8) NOT NULL", "message_key varchar(128) NOT NULL", "template_code varchar(64) NOT NULL", "template_version_no integer",
     "rule_id uuid", "source_event_id varchar(255)", "recipient_ref jsonb NOT NULL", "category varchar(12) NOT NULL", "channels varchar(8)[] NOT NULL",
     "params jsonb NOT NULL DEFAULT '{}'", "link varchar(500)", "mode varchar(8) NOT NULL DEFAULT 'ASYNC'", "priority varchar(8) NOT NULL DEFAULT 'NORMAL'",
     "status varchar(12) NOT NULL DEFAULT 'QUEUED'", "requested_at timestamptz NOT NULL DEFAULT now()", "dispatched_at timestamptz", "expires_at timestamptz"],
    [("uq_notification_message_key", "UNIQUE (tenant_id, caller_module, message_key)"), fk1("notification_message", "rule_id", "notification_rule"),
     chk("notification_message", "module", f"caller_module ~ '{MODULE_RE}'"),
     chk("notification_message", "recipient", "jsonb_typeof(recipient_ref) = 'array' AND jsonb_array_length(recipient_ref) BETWEEN 1 AND 500"),
     chk("notification_message", "category", "category IN ('TASK', 'JOB_RESULT', 'ALERT', 'INFO')"),
     chk("notification_message", "channels", "cardinality(channels) >= 1 AND channels <@ ARRAY['EMAIL', 'SMS', 'IN_APP']::varchar(8)[]"),
     chk("notification_message", "params", f"jsonb_typeof(params) = 'object' AND NOT (params ?| {NO_PII_PARAMS})"),
     chk("notification_message", "link", INTERNAL_LINK),
     chk("notification_message", "mode", "mode IN ('ASYNC', 'SYNC')"), chk("notification_message", "priority", "priority IN ('NORMAL', 'URGENT')"),
     chk("notification_message", "status", f"status IN {X(*ST_NOTIFY)}")],
    idx=["CREATE INDEX ix_notification_message_status ON @notification_message (tenant_id, status, requested_at);",
         "CREATE INDEX ix_notification_message_requested ON @notification_message (requested_at);"],
    trig=[("immutable", ["caller_module", "message_key", "template_code", "recipient_ref", "params"])], app_delete=True,
    ro_hide=["params", "recipient_ref"],
    sample={"caller_module": "'PH01'", "message_key": "'msg-0001'", "template_code": "'ph01.review-decided'",
            "recipient_ref": "'[{\"kind\": \"USER\", \"ref\": \"u-0001\"}]'::jsonb", "category": "'INFO'", "channels": "'{IN_APP}'"}))

G_NOTIFY.append(T("notification_delivery", "EN-18-23",
    "Lần gửi theo người nhận và kênh (nhật ký gửi): địa chỉ chỉ lưu dạng che và băm, trạng thái QUEUED sang SENT sang DELIVERED, BOUNCED hoặc FAILED; SUPPRESSED khi tùy chọn người dùng, giờ yên lặng, danh sách chặn. Kênh IN_APP là hộp thông báo DD-13 (read_at). Phân vùng tháng theo queued_at, giữ 18.notify.delivery-retention-days.",
    ["message_id uuid NOT NULL", "channel varchar(8) NOT NULL", "recipient_user_id varchar(64)", "recipient_masked varchar(64)", "recipient_hash char(64)",
     "status varchar(12) NOT NULL DEFAULT 'QUEUED'", "attempts integer NOT NULL DEFAULT 0", "provider_message_id varchar(255)", "rendered_title varchar(255)",
     "last_error varchar(1000)", "suppressed_reason varchar(20)", "queued_at timestamptz NOT NULL DEFAULT now()", "sent_at timestamptz", "delivered_at timestamptz",
     "bounced_at timestamptz", "read_at timestamptz"],
    [fk("notification_delivery", "message_id", "notification_message", cascade=True),
     chk("notification_delivery", "channel", "channel IN ('EMAIL', 'SMS', 'IN_APP')"),
     chk("notification_delivery", "status", f"status IN {X(*ST_NOTIFY)}"), chk("notification_delivery", "attempts", "attempts BETWEEN 0 AND 20"),
     chk("notification_delivery", "recipient", "recipient_user_id IS NOT NULL OR recipient_hash IS NOT NULL"),
     chk("notification_delivery", "hash", "recipient_hash IS NULL OR recipient_hash ~ '^[0-9a-f]{64}$'"),
     chk("notification_delivery", "in_app", "channel <> 'IN_APP' OR recipient_user_id IS NOT NULL"),
     chk("notification_delivery", "read", "read_at IS NULL OR channel = 'IN_APP'"),
     chk("notification_delivery", "suppressed", f"(status = 'SUPPRESSED') = (suppressed_reason IS NOT NULL) AND (suppressed_reason IS NULL OR suppressed_reason IN {X('USER_PREF', 'QUIET_HOURS', 'SUPPRESSION_LIST', 'DUPLICATE')})")],
    idx=["CREATE INDEX ix_notification_delivery_message ON @notification_delivery (tenant_id, message_id);",
         "CREATE INDEX ix_notification_delivery_inbox ON @notification_delivery (tenant_id, recipient_user_id, queued_at DESC) WHERE channel = 'IN_APP';",
         "CREATE INDEX ix_notification_delivery_pending ON @notification_delivery (status, queued_at) WHERE status = 'QUEUED';"],
    part=("queued_at", 4), tid=False,
    trig=[("immutable", ["message_id", "channel", "recipient_user_id", "recipient_hash"]),
          trans("status", ["QUEUED>SENT", "QUEUED>FAILED", "QUEUED>SUPPRESSED", "SENT>DELIVERED", "SENT>BOUNCED", "SENT>FAILED", "DELIVERED>BOUNCED"])],
    sample={"channel": "'IN_APP'", "recipient_user_id": "'u-0001'", "queued_at": "pg_temp.ts()"}))

