G_NOTIFY.append(T("suppression_entry", "EN-18-25",
    "Danh sách chặn gửi do thư trả lại cứng, khiếu nại, địa chỉ sai hoặc chặn tay: địa chỉ che và băm, số lần trả lại; thư trả lại phát ops.notification.bounced để PH-01 cập nhật đầu mối. Mỗi địa chỉ một dòng đang hiệu lực.",
    ["channel varchar(8) NOT NULL", "address_hash char(64) NOT NULL", "address_masked varchar(64) NOT NULL", "reason varchar(12) NOT NULL", "bounce_count integer NOT NULL DEFAULT 1",
     "first_bounced_at timestamptz NOT NULL DEFAULT now()", "last_bounced_at timestamptz NOT NULL DEFAULT now()", "released_at timestamptz", "released_by varchar(64)",
     "released_reason varchar(500)"],
    [chk("suppression_entry", "channel", "channel IN ('EMAIL', 'SMS')"), chk("suppression_entry", "hash", "address_hash ~ '^[0-9a-f]{64}$'"),
     chk("suppression_entry", "reason", f"reason IN {X('HARD_BOUNCE', 'COMPLAINT', 'INVALID', 'MANUAL')}"), chk("suppression_entry", "count", "bounce_count >= 1"),
     chk("suppression_entry", "released", "(released_at IS NULL) = (released_by IS NULL)")],
    idx=["CREATE UNIQUE INDEX uq_suppression_entry_active ON @suppression_entry (tenant_id, channel, address_hash) WHERE released_at IS NULL;"],
    trig=[("immutable", ["channel", "address_hash"])],
    sample={"channel": "'EMAIL'", "address_hash": "repeat('d', 64)", "address_masked": "'a***@t90.gov.vn'", "reason": "'HARD_BOUNCE'"}))
